    private void validarCampos(){
    
    if(txValor1.getText().trim().length() <= 0){
   
    JOptionPane.showMessageDialog(null, "Favol ingresar valor 1, el campo esta vacio.");
    txValor1.requestFocus();
    }
    else  if (txValor2.getText().trim().length() <= 0){
   
    JOptionPane.showMessageDialog(null, "Favol ingresar valor 2, el campo esta vacio.");
    txValor2.requestFocus();
    }
    
    }
    
    private void sumarValores (){
    Calculadora cal = new Calculadora();
    
    double respuesta = cal.sumar(Double.parseDouble(txValor1.getText()),Double.parseDouble(txValor2.getText()));
    txrespuesta.setText(respuesta + "");
    
    
    }
    private void restarValores() {

    Calculadora cal = new Calculadora();

    double respuesta = cal.resta( Double.parseDouble(txValor1.getText()),Double.parseDouble(txValor2.getText())
    );

    txrespuesta.setText(respuesta + "");
    
    
}
    
    
    
    private void multiplicarValores() {

    Calculadora cal = new Calculadora();

    double respuesta = cal.multiplicacion(Double.parseDouble(txValor1.getText()),Double.parseDouble(txValor2.getText())
    );

    txrespuesta.setText(respuesta + "");
}
    
    
    
 private void dividirValores() {

    Calculadora cal = new Calculadora();

    try {

        double respuesta = cal.dividir(
            Double.parseDouble(txValor1.getText()), Double.parseDouble(txValor2.getText()) );

        txrespuesta.setText(respuesta + "");

    } catch (ArithmeticException e) {

        JOptionPane.showMessageDialog(null, e.getMessage());
        txValor2.requestFocus();

    }
}
 
 
 
 private void convertirFahrenheitCelsius() {

    ConversorTemperatura conversor = new ConversorTemperatura();

    double respuesta = conversor.fahrenheitACelsius( Double.parseDouble(txValor1.getText()) );

    txrespuesta.setText(respuesta + "");
}
 
 
 
 
 private void convertirCelsiusFahrenheit() {

    ConversorTemperatura conversor = new ConversorTemperatura();

    double respuesta = conversor.celsiusAFahrenheit(Double.parseDouble(txValor1.getText())
    );

    txrespuesta.setText(respuesta + "");
}
 
 private void raizcuadrada(){
 
     Raizcuadrada_Exponente raiz1 = new Raizcuadrada_Exponente();
       double respuesta = raiz1.Raiz(Double.parseDouble(txValor1.getText())
    );

    txrespuesta.setText(respuesta + "");
 
 
 }
 
 
private void Exponencial() {

    Raizcuadrada_Exponente exponente1 = new Raizcuadrada_Exponente();

    double respuesta = exponente1.Exponente(Double.parseDouble(txValor1.getText()),Double.parseDouble(txValor2.getText())
    );

    txrespuesta.setText(respuesta + "");
}
 

 
 private boolean validarValor1() {

    if (txValor1.getText().trim().isEmpty()) {

        JOptionPane.showMessageDialog(null, "Favor ingresar el valor 1.");

        txValor1.requestFocus();

        return false;
    }

    return true;
}
 
 
 
 
 
 
    
    
    private void limpiarCampos(){
    
    txValor1.setText("");
    txValor2.setText("");
    txrespuesta.setText("");
    txValor1.requestFocus();

    }
    
    
    
    
